-------------------------------
---- ENVIRONMENT VARIABLES ----
-------------------------------

-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Environment-variables/

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")



-- Qt applications: qt6ct/qt5ct apply the md3 palette generated by matugen when
-- installed (sudo pacman -S qt6ct qt5ct); otherwise the portal provides dark mode.
local qt6ct = io.open("/usr/lib/qt6/plugins/platformthemes/libqt6ct.so", "r")
if qt6ct then
    qt6ct:close()
    hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
else
    hl.env("QT_QPA_PLATFORMTHEME", "xdgdesktopportal")
end
hl.env("QT_QUICK_CONTROLS_MATERIAL_THEME", "Dark")
hl.env("QT_QUICK_CONTROLS_UNIVERSAL_THEME", "Dark")

-- Let portals select the Hyprland backend and native Wayland dialogs.
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")

-- Include user and system Flatpak application and icon exports.
hl.env("XDG_DATA_DIRS", os.getenv("HOME") .. "/.local/share/flatpak/exports/share:/var/lib/flatpak/exports/share:" .. (os.getenv("XDG_DATA_DIRS") or "/usr/local/share:/usr/share"))
